INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/jiuwudaishi-115-copper-and-prisoners/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002736；EPUB电子本，纸本及异文待核", "id": "27b48fe9-8828-54dc-8c0c-4a460790b8d9"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/jiuwudaishi-115-huanghua-report/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002737；EPUB电子本，纸本及异文待核", "id": "863af785-0c18-553f-88b6-0f69f49f0a6e"}, {"title": "宋史·巻二百五十五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/songshi-255-huanghua-battle/source.txt", "note": "《宋史》巻二百五十五，段落 songshi-9c6e46fee832-p057569；EPUB电子本，纸本及异文待核", "id": "359dd667-58cd-5463-b7e4-135c73a0a45d"}, {"title": "宋史·巻二百七十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/songshi-274-zhaopin-identity/source.txt", "note": "《宋史》巻二百七十四，段落 songshi-9c6e46fee832-p059147；EPUB电子本，纸本及异文待核", "id": "5bd36963-a5b2-51ba-80e5-fb1ddf16c6f7"}, {"title": "宋史·巻二百七十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/songshi-274-zhaopin-surrender/source.txt", "note": "《宋史》巻二百七十四，段落 songshi-9c6e46fee832-p059148；EPUB电子本，纸本及异文待核", "id": "56cc8d30-35d9-5ce8-8a1d-b8e2f76efe1c"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7d5d8eead8288f56c81433a236a49d52b585665f/content/books/zizhi-tongjian/vol-292/year-0955/part-04/sources/library/tongjian-292-955-autumn-qinfeng/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003470；电子底本待考，分段待核", "id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/tongjian-292-955-qinfeng-first-order/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003469；电子底本待考，分段待核", "id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-zhangmei-eight-month/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002735；EPUB电子本，纸本及异文待核", "id": "17a4792f-88dd-5107-943a-14941d266127"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "景范", "aliases": ["景範"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长山人，后周枢密直学士、工部侍郎。954年七月癸巳获任中书侍郎、同平章事并判三司。《旧五代史》同记任命，名字作景範。生卒年未载。", "biography": null, "status": "draft", "id": "c6d39d95-b63f-5ce0-9263-66db615f1bc9"}, {"name": "王景（后晋耀州团练使）", "aliases": ["王景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "掖县人，曾任相州刺史。范延光叛乱时，他拒绝服从范延光。938年任耀州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "95c5e667-cc89-51aa-862e-471795aa6956"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "伊审征", "aliases": ["伊審徵", "伊审徵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员，太原人，《宋史》称伊审徵、字申图，记为并州人。951年由前云安榷盐使任通奏使、知枢密院事。关于母亲及其父婚配，两书叙述不同，具体对应仍待校核。生卒年尚未录入。", "biography": null, "status": "draft", "id": "a1611515-927b-50be-b3e4-084a6ff72a62"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "李进（后蜀先锋将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀先锋都指挥使。955年秦凤战事中，李廷珪派他据守马岭寨。与此前南汉交州将李进、洋州将李进唐缺少同人证据，分别保存。生卒年未载。", "biography": null, "status": "draft", "id": "018f1747-123c-5385-8f71-530a7d26be85"}, {"name": "张建雄", "aliases": ["張建雄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周将领。955年秦凤战事中，王景派他率二千人到黄花，配合截断后蜀军退路的部队击败蜀军。《宋史》向拱传称他为排阵使。生卒年未载。", "biography": null, "status": "draft", "id": "d2cfe5d0-ebba-59c1-9d76-f5e6ae168cd5"}, {"name": "王峦（后蜀染院使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀染院使。955年率军由唐仓出兵，在黄花交战失利。《通鉴》记他被俘，《旧五代史》本纪也记俘获，而该书引《九国志》记他战死。与此前后晋殿直王峦暂无同人证据，不作合并，死亡年份不据异说写死。", "biography": null, "status": "draft", "id": "0ddf1c28-fbbc-5656-a29e-1579e6c8fdaa"}, {"name": "高彦俦", "aliases": ["高彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高彦俦，太原人、昭武都监、拟领兵者。", "biography": null, "status": "draft", "id": "b335c31e-ee43-595d-8eb5-e601824ba527"}, {"name": "韩继勋", "aliases": ["韓繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩继勋，医官使、曾事藩邸者。", "biography": null, "status": "draft", "id": "3327c23e-cf6f-54fb-a0c6-0077fa06e1ec"}, {"name": "赵玭", "aliases": ["趙玭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "澶州人，后蜀秦州观察判官。955年秦凤战事中带秦州归降后周。柴荣拟任其为节度使，范质反对，最后任郢州刺史。《宋史》本传补充其闭城门拒纳败军、召官属商议归降的经过。生卒年未载。", "biography": null, "status": "draft", "id": "c38a9283-05e4-5b7a-9690-3bee724b01a3"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "王溥（后周宋初）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "949年为秘书郎，在河中平定后劝郭威焚毁涉及朝臣、藩镇的往来书信，《宋史》王溥传也记此事。与901年条所载同名王溥分开建档。生卒年留待具体原文补录。", "biography": null, "status": "draft", "id": "13d3b7ec-869a-5019-ac41-39e5abcd2df3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "景范停止兼管三司事务", "start_year": 955, "end_year": 955, "time_original": "955年八月丁未", "dynasty": "五代十国", "description": "景范停止兼管三司事务。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9808235e-61d5-5489-8857-8356d35c02b9"}, {"title": "景范随后因父亲去世而停止政务", "start_year": 955, "end_year": 955, "time_original": "955年八月罢判三司之后不久，具体日未载", "dynasty": "五代十国", "description": "景范随后因父亲去世而停止政务。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7e0dde9c-d23d-5ad0-b2f6-906ceef74132"}, {"title": "王景等击败后蜀军，俘获将卒三百人", "start_year": 955, "end_year": 955, "time_original": "955年八月段所记，具体交战日未载", "dynasty": "五代十国", "description": "王景等击败后蜀军，俘获将卒三百人。", "phases": [], "location_name": "秦凤战场", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ace1de86-0633-5db9-9d9c-ca84fc7a802f"}, {"title": "孟昶派伊审征到行营慰劳并督战", "start_year": 955, "end_year": 955, "time_original": "955年八月己未", "dynasty": "五代十国", "description": "孟昶派伊审征到行营慰劳并督战。", "phases": [], "location_name": "后蜀行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "add97d34-2c85-505d-83e9-be6b0f327a73"}, {"title": "柴荣因钱币短缺，下令设监采铜铸钱", "start_year": 955, "end_year": 955, "time_original": "955年九月丙寅朔", "dynasty": "五代十国", "description": "《通鉴》记官府久未铸钱，民间又熔钱制作器皿和佛像，钱币愈少。柴荣因此下令设监采铜铸钱。这里县官指官府，不是某名县令；诏令不等于所有铸钱机构当日已经建成。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dae3e7c5-795b-57d4-9b01-bf8fe256a87d"}, {"title": "柴荣要求五十日内交纳部分铜器与佛像，并给付价款", "start_year": 955, "end_year": 955, "time_original": "955年九月丙寅朔诏令，交纳期限五十日", "dynasty": "五代十国", "description": "除官府法物、军器，以及寺观钟、磬、钹、铎等获准保留的物件外，民间铜器和铜佛像须在五十日内交给官府，官府给付价款。没有把所有宗教用品都列为征收对象，也未记录每户实际成交金额。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a78cd5f-0d75-5444-b03f-3bba2cfa7b5f"}, {"title": "柴荣规定逾期藏匿应交铜器的处罚", "start_year": 955, "end_year": 955, "time_original": "955年九月丙寅朔诏令，五十日期满后适用", "dynasty": "五代十国", "description": "应交铜器逾期被隐匿不交，藏匿五斤以上者处死，不满五斤者按数量分别处罚。这里是诏令规定，史书本段没有列出已被处死的具体案件。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dae6110a-0b4a-50dc-9a39-078b3029d332"}, {"title": "柴荣向侍臣解释征收铜佛像的理由", "start_year": 955, "end_year": 955, "time_original": "955年九月征铜铸钱政策时，讲话具体日未单列", "dynasty": "五代十国", "description": "柴荣告诉侍臣，不必因毁损佛像而疑虑：佛以善道教化，行善才是奉佛，铜像本身并不是佛；若自己的身体能帮助百姓，也不应吝惜。这是柴荣解释政策时的讲话，不作本站对佛教教义的裁定。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "db47bc64-2254-52ec-839e-d1a507e5fcf8"}, {"title": "李廷珪派兵据马岭、白涧等地，试图截断周军粮道", "start_year": 955, "end_year": 955, "time_original": "955年闰月黄花战役以前，具体布兵日未载", "dynasty": "五代十国", "description": "李廷珪派兵据马岭、白涧等地，试图截断周军粮道。", "phases": [], "location_name": "马岭寨、斜谷、白涧、凤州北唐仓镇及黄花谷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "00cb47cb-40a8-5ba9-a82f-4be8621a01af"}, {"title": "王景派张建雄赴黄花，并派另一支部队截断蜀军退路", "start_year": 955, "end_year": 955, "time_original": "955年闰月，具体出兵日未载", "dynasty": "五代十国", "description": "王景派张建雄率二千兵到黄花，又派一千兵赴唐仓扼守蜀军归路。第二路将领未具名，二千人与一千人是两支部队，不是俘虏数。", "phases": [], "location_name": "黄花至唐仓", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "52fa02f1-20e0-5f6f-80bd-fbcf4e8100e9"}, {"title": "张建雄等在黄花、唐仓接连击败王峦所部", "start_year": 955, "end_year": 955, "time_original": "955年闰月，具体交战日未载", "dynasty": "五代十国", "description": "后蜀染院使王峦率兵由唐仓出发，在黄花被张建雄击败，退回唐仓又遇周军而败。《通鉴》记王峦及其将士三千人被俘；《旧五代史》《宋史》记一千五百余人，旧史引《九国志》还记王峦战死，数量和生死差异均保留。", "phases": [], "location_name": "黄花及唐仓", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5680f013-c798-5b63-a0f9-e8e41f402b33"}, {"title": "李廷珪、高彦俦等因军队溃败退守青泥岭", "start_year": 955, "end_year": 955, "time_original": "955年闰月黄花战役之后", "dynasty": "五代十国", "description": "李廷珪、高彦俦等因军队溃败退守青泥岭。", "phases": [], "location_name": "马岭、白涧至青泥岭", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bea8c334-9167-544f-bb37-a2cd66ae034c"}, {"title": "韩继勋放弃秦州，逃回成都", "start_year": 955, "end_year": 955, "time_original": "955年闰月蜀军失利之后", "dynasty": "五代十国", "description": "韩继勋放弃秦州，逃回成都。", "phases": [], "location_name": "秦州至成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6f72a772-0f1c-52a7-a5c7-9d58b4598a19"}, {"title": "赵玭率秦州归降后周", "start_year": 955, "end_year": 955, "time_original": "955年闰月蜀军败退之后，《资治通鉴》未单列归降日", "dynasty": "五代十国", "description": "赵玭率秦州归降后周。", "phases": [], "location_name": "秦州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1f8a7edd-3045-5ef4-b7a0-7908b9f00bfd"}, {"title": "成州、阶州归降，后蜀人心震恐", "start_year": 955, "end_year": 955, "time_original": "955年闰月秦州归降前后，具体日未载", "dynasty": "五代十国", "description": "成州、阶州归降，后蜀人心震恐。", "phases": [], "location_name": "成州、阶州及后蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "28a27faa-f241-5aea-afa5-f2d5c7b76c4b"}, {"title": "柴荣拟任赵玭为节度使，范质反对后改任郢州刺史", "start_year": 955, "end_year": 955, "time_original": "955年闰月秦州归降之后，具体任命日未载", "dynasty": "五代十国", "description": "柴荣拟任赵玭为节度使，范质反对后改任郢州刺史。", "phases": [], "location_name": "后周朝廷及郢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dabc10dc-e1b4-5e2b-8b42-386dee36d603"}, {"title": "柴荣在群臣庆功时称赞王溥选将有功", "start_year": 955, "end_year": 955, "time_original": "955年闰月壬子", "dynasty": "五代十国", "description": "柴荣在群臣庆功时称赞王溥选将有功。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a733c314-1f3d-5daa-8c4a-91e654bf6759"}, {"title": "柴荣在万岁殿与将相用餐，表示愿冒险为百姓除害", "start_year": 955, "end_year": 955, "time_original": "955年闰月甲子", "dynasty": "五代十国", "description": "柴荣与将相在万岁殿用餐，谈到这两日大寒，自己在宫中享用珍膳而未亲耕，感到惭愧，因此希望亲冒矢石为百姓除害。这是柴荣当时的责任表态，不是本段已发生的亲征行动。", "phases": [], "location_name": "万岁殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e1d68fc3-cffa-5d88-9e16-a1829ea9bfcd"}, {"title": "李廷珪上表请罪", "start_year": 955, "end_year": 955, "time_original": "955年闰月乙丑", "dynasty": "五代十国", "description": "李廷珪上表请罪。", "phases": [], "location_name": "后蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "def1d1ff-2857-588b-867e-a4a4f5621c44"}, {"title": "伊审征回到成都请罪，孟昶宽免他和李廷珪", "start_year": 955, "end_year": 955, "time_original": "955年十月壬申伊审征到成都；宽免具体日未另载", "dynasty": "五代十国", "description": "伊审征回到成都请罪，孟昶宽免他和李廷珪。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4bc2cfb2-78da-539c-b242-caa08a08e227"}, {"title": "孟昶以大蜀皇帝名义向柴荣请和，柴荣不予回复", "start_year": 955, "end_year": 955, "time_original": "955年十月请罪记载之后，具体送信日未载", "dynasty": "五代十国", "description": "孟昶致书柴荣请求和解，自称大蜀皇帝。柴荣因孟昶仍以对等皇帝称号行礼而生气，没有答复。请和、称号争执与未答复分别说明，不能记作已经签订和约。", "phases": [], "location_name": "后蜀至后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "00e20c2d-2e6f-5248-a719-018b0745b533"}, {"title": "孟昶在剑门、白帝集结兵粮，准备防守", "start_year": 955, "end_year": 955, "time_original": "955年十月请和未获答复以后，具体日未载", "dynasty": "五代十国", "description": "孟昶在剑门、白帝集结兵粮，准备防守。", "phases": [], "location_name": "剑门、白帝", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bdf8f135-92b7-56ab-b79b-ecdd6c9bc8d4"}, {"title": "孟昶因募兵开支不足开始铸铁钱，并专管境内铁器", "start_year": 955, "end_year": 955, "time_original": "955年十月段所记备守之后，具体日未载", "dynasty": "五代十国", "description": "孟昶募兵增多而费用不足，开始铸造铁钱，并对境内铁器实行榷管。《通鉴》记百姓因此深受困扰。榷为官府专管，不自行推定具体收购价格、铸币兑换比例或民户损失金额。", "phases": [], "location_name": "后蜀境内", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dd76414e-58ab-5ec2-9421-dd0ba5cf580d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

